def is_even(n):
    return n % 2 == 0


def describe(n):
    if is_even(n):
        return "偶数"
    return "奇数"


def print_double(n):
    print(n * 2)


def find_first_even(nums):
    for x in nums:
        if x % 2 == 0:
            return x        # 直接结束整个函数，后面的元素不再检查
    return None             # 循环跑完都没找到


print(describe(7), describe(8))
print("is_even(10) ->", is_even(10))
y = print_double(6)
print("print_double 的返回值 ->", y)
print("第一个偶数 ->", find_first_even([1, 3, 8, 10]))
print("找不到时 ->", find_first_even([1, 3, 5]))

def is_leap_year(year):
    return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0


def get_days_in_month(year, month):
    if month in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if month in (4, 6, 9, 11):
        return 30
    return 29 if is_leap_year(year) else 28


def get_total_days(year, month):
    total = 0
    for y in range(1800, year):
        total += 366 if is_leap_year(y) else 365
    for m in range(1, month):
        total += get_days_in_month(year, m)
    return total


def get_start_day(year, month):
    return (get_total_days(year, month) + 3) % 7   # 0=周日 ... 6=周六


def print_month_title(year, month):
    month_names = ["", "一月", "二月", "三月", "四月", "五月", "六月",
                   "七月", "八月", "九月", "十月", "十一月", "十二月"]
    print("        {} {}".format(month_names[month], year))
    print("-" * 28)
    print(" Sun Mon Tue Wed Thu Fri Sat")


def print_month_body(year, month):
    start_day = get_start_day(year, month)
    days = get_days_in_month(year, month)
    for _ in range(start_day):
        print("    ", end="")
    for day in range(1, days + 1):
        print("{:4d}".format(day), end="")
        if (day + start_day) % 7 == 0:
            print()
    if (days + start_day) % 7 != 0:
        print()


def print_month(year, month):
    print_month_title(year, month)
    print_month_body(year, month)


print_month(2024, 2)

