def whileGCD(one, two):
    while two != 0:
        one, two = two, one % two
    return one


def forLCM(one, two):
    for i in range(max(one, two), one * two + 1):
        if i % one == 0 and i % two == 0:
            return i


a, b = map(int, input().split())
g = whileGCD(a, b)
