def is_prime(x):
    if x < 2:
        return False
    i = 2
    while i * i <= x:
        if x % i == 0:
            return False
        i += 1
    return True


def is_reversible_prime(n):
    rev = int(str(n)[::-1])
    return is_prime(n) and is_prime(rev)


def goldbach(even):
    for p in range(2, even):
        q = even - p
        if is_prime(p) and is_prime(q):
            return p, q


def main():
    n = int(input())
    even = int(input())
    print("yes" if is_reversible_prime(n) else "no")
    p, q = goldbach(even)
    print(f"{even}={p}+{q}")


main()

def yinzihe(n):
    s = 0
    for i in range(1, n):
        if n % i == 0:
            s += i
    return s


def print_amicable_pairs(limit):
    for a in range(2, limit):
        b = yinzihe(a)
        if b > a and b < limit and yinzihe(b) == a:
            print(a, b)


def is_leap(year):
    return (year % 4 == 0 and year % 100 != 0) or year % 400 == 0


def days_in_month(year, month):
    if month in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if month in (4, 6, 9, 11):
        return 30
    return 29 if is_leap(year) else 28


def total_days_from_base(year, month):
    total = 0
    for y in range(1800, year):
        total += 366 if is_leap(y) else 365
    for m in range(1, month):
        total += days_in_month(year, m)
    return total


def weekday_name(year, month):
    names = ["星期日", "星期一", "星期二", "星期三",
             "星期四", "星期五", "星期六"]
    return names[(total_days_from_base(year, month) + 3) % 7]


def main():
    limit = int(input())
    year, month = map(int, input().split())
    print_amicable_pairs(limit)
    print(weekday_name(year, month))


main()

